'use strict';

/**
* Compute the cumulative maximum of double-precision floating-point strided array elements.
*
* @module @stdlib/stats/strided/wasm/dcumax
*
* @example
* var Float64Array = require( '@stdlib/array/float64' );
* var dcumax = require( '@stdlib/stats/strided/wasm/dcumax' );
*
* // Define strided arrays:
* var x = new Float64Array( [ 1.0, -2.0, 2.0 ] );
* var y = new Float64Array( x.length );
*
* // Perform operation:
* dcumax.main( x.length, x, 1, y, 1 );
* // y => <Float64Array>[ 1.0, 1.0, 2.0 ]
*
* @example
* var Float64Array = require( '@stdlib/array/float64' );
* var dcumax = require( '@stdlib/stats/strided/wasm/dcumax' );
*
* // Define strided arrays:
* var x = new Float64Array( [ 2.0, 1.0, 2.0, -2.0, -2.0, 2.0, 3.0, 4.0 ] );
* var y = new Float64Array( x.length );
*
* // Perform operation:
* dcumax.ndarray( 4, x, 2, 1, y, 1, 0 );
* // y => <Float64Array>[ 1.0, 1.0, 2.0, 4.0, 0.0, 0.0, 0.0, 0.0 ]
*
* @example
* var Memory = require( '@stdlib/wasm/memory' );
* var zeros = require( '@stdlib/array/zeros' );
* var Float64Array = require( '@stdlib/array/float64' );
* var bytesPerElement = require( '@stdlib/ndarray/base/bytes-per-element' );
* var dcumax = require( '@stdlib/stats/strided/wasm/dcumax' );
*
* // Create a new memory instance with an initial size of 10 pages (640KiB) and a maximum size of 100 pages (6.4MiB):
* var mem = new Memory({
*     'initial': 10,
*     'maximum': 100
* });
*
* // Create a STATS routine:
* var mod = new dcumax.Module( mem );
* // returns <Module>
*
* // Initialize the routine:
* mod.initializeSync();
*
* // Define a vector data type:
* var dtype = 'float64';
*
* // Specify a vector length:
* var N = 5;
*
* // Define pointers (i.e., byte offsets) for storing two vectors:
* var xptr = 0;
* var yptr = N * bytesPerElement( dtype );
*
* // Define strided array:
* var arr = new Float64Array( [ 1.0, -2.0, 2.0, -3.0, 3.0 ] );
*
* // Write vector values to module memory:
* mod.write( xptr, arr );
* mod.write( yptr, zeros( N, dtype ) );
*
* // Perform computation:
* mod.main( N, xptr, 1, yptr, 1 );
*
* // Read out the results:
* var view = zeros( N, dtype );
* mod.read( yptr, view );
*
* console.log( view );
* // => <Float64Array>[ 1.0, 1.0, 2.0, 2.0, 3.0 ]
*/

// MODULES //

var setReadOnly = require( '@stdlib/utils/define-nonenumerable-read-only-property' );
var main = require( './main.js' );
var Module = require( './module.js' );


// MAIN //

setReadOnly( main, 'Module', Module );


// EXPORTS //

module.exports = main;

// exports: { "Module": "main.Module" }
